content.solution_code:
class Starship {
  #fuelLevel;

  constructor(name) {
    this.name = name;
    this.#fuelLevel = 100;
    this.MAX_FUEL = 200;
  }

  refuel(amount) {
    if (amount <= 0) {
      return "Refuel amount must be positive.";
    }
    this.#fuelLevel = Math.min(this.#fuelLevel + amount, this.MAX_FUEL);
    return `Starship ${this.name} refueled by ${amount}. Current fuel: ${this.#fuelLevel}.`;
  }

  fly(distance) {
    const fuelNeeded = Math.ceil(distance / 10);
    if (this.#fuelLevel >= fuelNeeded) {
      this.#fuelLevel -= fuelNeeded;
      return `Starship ${this.name} flew ${distance} units. Remaining fuel: ${this.#fuelLevel}.`;
    } else {
      return `Not enough fuel for Starship ${this.name} to fly ${distance} units. Current fuel: ${this.#fuelLevel}.`;
    }
  }

  getFuelLevel() {
    return this.#fuelLevel;
  }
}

